# Load existing mock entities
with open('public/api_entities_mock.json', 'r', encoding='utf-8') as f:
    existing_entities = json.load(f)

existing_ids = {e['id'] for e in existing_entities}
existing_slugs = {e.get('slug') for e in existing_entities if e.get('slug')}
existing_names = {e.get('name', '').lower() for e in existing_entities if e.get('name')}

added = 0
updated = 0

for new_e in new_entities:
    # Check if exists by id, slug, or name
    matched_idx = -1
    for idx, e in enumerate(existing_entities):
        if e['id'] == new_e['id'] or (e.get('slug') and e.get('slug') == new_e['slug']) or e.get('name', '').lower() == new_e['name'].lower():
            matched_idx = idx
            break
            
    if matched_idx >= 0:
        # Update existing
        existing_entities[matched_idx] = {**existing_entities[matched_idx], **new_e}
        updated += 1
    else:
        # Prepend to entities so they are easily accessible and prominent
        existing_entities.insert(0, new_e)
        added += 1

print(f"Added {added} new entities, updated {updated} existing entities.")
print(f"Total entities now: {len(existing_entities)}")

# Save updated api_entities_mock.json
with open('public/api_entities_mock.json', 'w', encoding='utf-8') as f:
    json.dump(existing_entities, f, indent=2, ensure_ascii=False)

print("Saved public/api_entities_mock.json successfully!")

# Also generate SQL for D1
sql_statements = []
for e in new_entities:
    eid = e['id']
    etype = e['type']
    name = e['name'].replace("'", "''")
    slug = e['slug'].replace("'", "''")
    desc = e['description'].replace("'", "''")
    tagline = e['tagline'].replace("'", "''")
    role = e['role']
    stance = e['stance']
    url = e['url'].replace("'", "''")
    image_url = e.get('image_url', '').replace("'", "''")
    featured = e.get('featured', 0)
    
    sql = f"""INSERT INTO entities (id, type, name, slug, description, bio, tagline, role, stance, url, image_url, featured)
VALUES ('{eid}', '{etype}', '{name}', '{slug}', '{desc}', '{desc}', '{tagline}', '{role}', '{stance}', '{url}', '{image_url}', {featured})
ON CONFLICT(id) DO UPDATE SET 
  description = excluded.description,
  bio = excluded.bio,
  tagline = excluded.tagline,
  role = excluded.role,
  stance = excluded.stance,
  slug = excluded.slug,
  url = excluded.url,
  featured = excluded.featured;"""
    sql_statements.append(sql)

with open('scripts/add_manifest_entities_d1.sql', 'w', encoding='utf-8') as f:
    f.write("\n\n".join(sql_statements))

print("Generated scripts/add_manifest_entities_d1.sql with D1 upsert queries!")
